messages.content:
{
  "framework": "cube",
  "question": "ORG_1001 在 2026 年上半年，按产品一级分类统计设备订货金额和设备利润。",
  "current_date": "2026-08-04",
  "semantic_context": {
    "source": "actual Cube Core /cubejs-api/v1/meta response",
    "scope_strategy": "full metadata after hard scoping to the device domain",
    "cube": {
      "name": "DeviceOrders",
      "title": "设备订货事实",
      "description": "合成数据。每行是一张设备订货单；指标只统计 confirmed 状态。本模型用于设备订货，不用于销售金额。",
      "measures": [
        {
          "name": "DeviceOrders.deviceOrderAmount",
          "title": "设备订货事实 设备订货金额",
          "description": "已确认设备订货单的 order_amount 合计，演示单位 CNY.",
          "type": "number",
          "meta": {
            "ai_context": "同义词包括“设备订货额”和“设备订单金额”。不能用于“销售金额”。"
          }
        },
        {
          "name": "DeviceOrders.deviceProfitAmount",
          "title": "设备订货事实 设备利润金额",
          "description": "已确认设备订货单的设备利润合计；不能解释为净利润。",
          "type": "number",
          "meta": {
            "ai_context": "同义词包括“设备利润额”。用户明确询问净利润时不得使用本指标。"
          }
        },
        {
          "name": "DeviceOrders.orderCount",
          "title": "设备订货事实 Order Count",
          "type": "number"
        }
      ],
      "dimensions": [
        {
          "name": "DeviceOrders.orderId",
          "title": "设备订货事实 Order ID",
          "type": "string"
        },
        {
          "name": "DeviceOrders.orderDate",
          "title": "设备订货事实 Order Date",
          "type": "time"
        },
        {
          "name": "DeviceOrders.yearMonth",
          "title": "设备订货事实 Year Month",
          "type": "number"
        },
        {
          "name": "DeviceOrders.orgCode",
          "title": "设备订货事实 Org Code",
          "description": "组织编码；每次设备经营分析必须由用户显式给出。",
          "type": "string",
          "meta": {
            "ai_context": "必填过滤维度；不得默认跨组织汇总，也不得猜测组织编码。"
          }
        },
        {
          "name": "DeviceOrders.productL1",
          "title": "设备订货事实 产品一级分类",
          "type": "string",
          "meta": {
            "ai_context": "“产品大类”在本模型中指产品一级分类。"
          }
        },
        {
          "name": "DeviceOrders.status",
          "title": "设备订货事实 Status",
          "type": "string"
        }
      ]
    }
  },
  "required_output": {
    "status": "ready | needs_clarification | unsupported",
    "reason": "简洁说明为什么做出这一判断",
    "clarification_question": "需要追问时填写字符串，否则为 null",
    "query": {
      "measures": "仅允许 DeviceOrders.deviceOrderAmount、DeviceOrders.deviceProfitAmount、DeviceOrders.orderCount",
      "dimensions": "仅允许 DeviceOrders.productL1、DeviceOrders.yearMonth、DeviceOrders.orgCode、DeviceOrders.status",
      "timeDimensions": [
        {
          "dimension": "仅允许 DeviceOrders.orderDate",
          "dateRange": [
            "YYYY-MM-DD",
            "YYYY-MM-DD"
          ]
        }
      ],
      "filters": [
        {
          "member": "上下文中的正式 Dimension ID",
          "operator": "equals",
          "values": [
            "过滤值"
          ]
        }
      ],
      "order": {
        "正式 Dimension ID": "asc | desc"
      }
    },
    "query_note": "status 不是 ready 时，query 必须为 null"
  }
}

llm.raw_response:
{
  "status": "ready",
  "reason": "指标(设备订货金额、设备利润)、分组(产品一级分类)、组织(ORG_1001)、时间范围(2026年上半年)均已明确且与语义层一致。",
  "clarification_question": null,
  "query": {
    "measures": [
      "DeviceOrders.deviceOrderAmount",
      "DeviceOrders.deviceProfitAmount"
    ],
    "dimensions": [
      "DeviceOrders.productL1"
    ],
    "timeDimensions": [
      {
        "dimension": "DeviceOrders.orderDate",
        "dateRange": [
          "2026-01-01",
          "2026-06-30"
        ]
      }
    ],
    "filters": [
      {
        "member": "DeviceOrders.orgCode",
        "operator": "equals",
        "values": [
          "ORG_1001"
        ]
      }
    ],
    "order": {
      "DeviceOrders.productL1": "asc"
    }
  },
  "query_note": "指标已内置仅统计 confirmed 状态；时间使用 orderDate 闭区间，orgCode 必填过滤已满足。"
}
